        return;

    qs_minmax(values->v, values->len, &out->min, &out->max);
    out->mean = qs_mean(values->v, values->len);
    out->stdev = qs_stdev(values->v, values->len, out->mean);

    struct qs_vec sorted;
    qs_vec_init(&sorted);
